 177	// ── Disk-backed config with mtime caching ──────────────────────────────────
 178	
 179	export const NOTES_CONFIG_PATH = path.join(WorkDir, "config", "notes.json");
 180	
 181	let cachedNoteTypeDefinitions: NoteTypeDefinition[] | null = null;
 182	let cachedMtimeMs: number | null = null;
 183	
 184	function ensureNotesConfigSync(): void {
 185	  if (!fs.existsSync(NOTES_CONFIG_PATH)) {
 186	    fs.writeFileSync(
 187	      NOTES_CONFIG_PATH,
 188	      JSON.stringify(DEFAULT_NOTE_TYPE_DEFINITIONS, null, 2) + "\n",
 189	      "utf8",
 190	    );
 191	  }
 192	}
 193	
 194	export function getNoteTypeDefinitions(): NoteTypeDefinition[] {
 195	  ensureNotesConfigSync();
 196	  try {
 197	    const stats = fs.statSync(NOTES_CONFIG_PATH);
 198	    if (cachedNoteTypeDefinitions && cachedMtimeMs === stats.mtimeMs) {
 199	      return cachedNoteTypeDefinitions;
 200	    }
 201	    const content = fs.readFileSync(NOTES_CONFIG_PATH, "utf8");
 202	    cachedNoteTypeDefinitions = JSON.parse(content);
 203	    cachedMtimeMs = stats.mtimeMs;
 204	    return cachedNoteTypeDefinitions!;
 205	  } catch {
 206	    cachedNoteTypeDefinitions = null;
 207	    cachedMtimeMs = null;
 208	    return DEFAULT_NOTE_TYPE_DEFINITIONS;
 209	  }
 210	}
 211	
 212	// ── Render helper ────────────────────────────────────────────────────────
 213	
 214	function assistantNotesPlaceholder(type: string): string {
 215	  const normalized = type.toLowerCase();
 216	  if (normalized === "people") {
 217	    return "person";
 218	  }
 219	  if (normalized === "organizations") {
 220	    return "organization";
 221	  }
 222	  if (normalized === "projects") {
 223	    return "project";
 224	  }
 225	  if (normalized === "topics") {
 226	    return "topic";
 227	  }
 228	  return "entity";
 229	}
 230	
 231	function renderTemplateWithAssistantNotes(def: NoteTypeDefinition): string {
 232	  if (!["People", "Organizations", "Projects", "Topics"].includes(def.type)) {
 233	    return def.template;
 234	  }
 235	  if (/^## Assistant notes\b/im.test(def.template)) {
 236	    return def.template;
 237	  }
 238	  const target = assistantNotesPlaceholder(def.type);
 239	  return `${def.template.trimEnd()}\n\n## Assistant notes\n- [{ISO_TIMESTAMP}] {One concise assistant-facing observation about this ${target}.}`;
 240	}
 241	
 242	export function renderNoteTypesBlock(): string {
 243	  const defs = getNoteTypeDefinitions();
 244	  const sections = defs.map(
 245	    (d) =>
 246	      `## ${d.type}\n\`\`\`markdown\n${renderTemplateWithAssistantNotes(d)}\n\`\`\``,
 247	  );
 248	  return `# Note Templates\n\n${sections.join("\n\n")}`;
 249	}

